//! These fixed bytes were generated by Node/OpenSSL in GitHub Actions, not Rust.
use nestlink_identity::{digest, network::*};
use nestlink_protocol::network::*;
use std::collections::BTreeSet;

fn hex<const N: usize>(value: &str) -> Result<[u8; N], Box<dyn std::error::Error>> {
    if value.len() != N * 2 || !value.is_ascii() {
        return Err("invalid reference hex".into());
    }
    let mut output = [0u8; N];
    for (i, byte) in output.iter_mut().enumerate() {
        *byte = u8::from_str_radix(&value[i * 2..i * 2 + 2], 16)?;
    }
    Ok(output)
}

#[test]
fn independent_openssl_ed25519_hkdf_and_canonical_claims_vector()
-> Result<(), Box<dyn std::error::Error>> {
    let vector: serde_json::Value =
        serde_json::from_str(include_str!("fixtures/network-v1-reference.json"))?;
    let text = |name| {
        vector
            .get(name)
            .and_then(serde_json::Value::as_str)
            .ok_or("missing reference field")
    };
    let authority_key = hex::<32>(text("authority_public_key_hex")?)?;
    let member_key = hex::<32>(text("member_public_key_hex")?)?;
    let seed = hex::<32>(text("public_test_master_seed_hex")?)?;
    let signer = NetworkAuthoritySigner::from_master_seed(&seed)?;
    assert_eq!(signer.public_key(), authority_key);
    let signed = SignedNetworkGrant {
        claims: text("canonical_claims_utf8")?.as_bytes().to_vec(),
        signature: hex::<64>(text("signature_hex")?)?.to_vec(),
    };
    let revoked = BTreeSet::new();
    let context = NetworkVerification {
        authority_key: &authority_key,
        deployment_id: "10000000-0000-4000-8000-000000000001",
        space_id: "20000000-0000-4000-8000-000000000002",
        policy_epoch: 7,
        now_ms: 1500,
        revoked_grant_ids: &revoked,
    };
    let verified = verify_network_grant(&signed, &context)?;
    assert_eq!(verified.claims().canonical_bytes()?, signed.claims);
    assert_eq!(
        digest(&verified.claims().signing_message()?),
        hex::<32>(text("signing_message_sha256")?)?
    );
    assert_eq!(signer.sign(verified.claims())?.signature, signed.signature);
    let member = VerifiedMembership::from_grant(
        verified,
        &context,
        "40000000-0000-4000-8000-000000000004",
        &member_key,
        3,
    )?;
    assert_eq!(member.claims().role, SpaceRole::Member);
    let mut tampered = signed;
    tampered.claims = String::from_utf8(tampered.claims)?
        .replace("\"policy_epoch\":7", "\"policy_epoch\":8")
        .into_bytes();
    assert!(verify_network_grant(&tampered, &context).is_err());
    Ok(())
}
